world_checks.check_files_and_fixtures:
def check(world):
    state = world.state()
    files = state.get("files", [])
    if len(files) < 25:
        return f"World has only {len(files)} files, expected at least 25."
    deleted = [f for f in files if f.get("is_deleted")]
    if not deleted:
        return "World lacks deleted file edge fixture."
    binary = [f for f in files if f.get("mime_type") == "application/octet-stream"]
    if not binary:
        return "World lacks binary unsupported file edge fixture."
    return None

world_checks.check_users_and_acls:
def check(world):
    state = world.state()
    users = state.get("users", [])
    if len(users) < 5:
        return f"Expected at least 5 users, found {len(users)}."
    perms = state.get("permissions", [])
    if len(perms) < 10:
        return f"Expected at least 10 permissions rows, found {len(perms)}."
    folders = state.get("folders", [])
    if len(folders) < 3:
        return f"Expected at least 3 folders, found {len(folders)}."
    return None
